begin;

create extension if not exists pgcrypto;

create table organizations (id text primary key, name text not null check(length(trim(name)) between 1 and 160), timezone text not null default 'Asia/Makassar', settings_json jsonb not null default '{}'::jsonb, version integer not null default 1 check(version>0), created_at text not null, updated_at text not null);
create table users (id text primary key, organization_id text not null references organizations(id), email text not null, display_name text not null, status text not null default 'inactive' check(status in ('active','inactive','suspended')), last_login_at text, version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, unique(organization_id,email), unique(organization_id,id));
create unique index users_org_email_ci on users(organization_id,lower(email));
create table roles (id text primary key, code text not null unique check(code in ('super_admin','admin','worship_coordinator','field_coordinator','servant','public_viewer')), name text not null, system_managed integer not null default 1 check(system_managed=1));
create table permissions (id text primary key, code text not null unique, description text not null);
create table role_permissions (role_id text not null references roles(id), permission_id text not null references permissions(id), primary key(role_id,permission_id));
create table user_roles (id text primary key, organization_id text not null references organizations(id), user_id text not null, role_id text not null references roles(id), granted_by text not null, granted_at text not null, revoked_at text, version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, foreign key(organization_id,user_id) references users(organization_id,id), foreign key(organization_id,granted_by) references users(organization_id,id));
create unique index user_roles_active on user_roles(organization_id,user_id,role_id) where revoked_at is null;
create table coordinator_scopes (id text primary key, organization_id text not null references organizations(id), user_id text not null, scope_type text not null check(scope_type in ('service','field')), scope_id text not null, starts_at text not null, ends_at text check(ends_at is null or ends_at>starts_at), version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, foreign key(organization_id,user_id) references users(organization_id,id));
create index scopes_actor on coordinator_scopes(organization_id,user_id,scope_type,scope_id);
create table audit_logs (id text primary key, organization_id text not null references organizations(id), actor_type text not null check(actor_type in ('user','system')), actor_id text, action text not null, entity_type text not null, entity_id text not null, request_id text not null, metadata_redacted_json jsonb not null default '{}'::jsonb, created_at text not null, foreign key(organization_id,actor_id) references users(organization_id,id));
create index audit_org_time on audit_logs(organization_id,created_at,id);

create table role_changes (id text primary key, organization_id text not null references organizations(id), actor_id text not null, user_id text not null, idempotency_key text not null, roles_json jsonb not null, expected_version integer not null, actual_version integer not null, actor_authorized boolean not null constraint role_actor_authorized check(actor_authorized), target_exists boolean not null constraint role_target_exists check(target_exists), preserves_admin boolean not null constraint role_preserves_admin check(preserves_admin), created_at text not null, constraint role_version_matches check(expected_version=actual_version), unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,user_id) references users(organization_id,id));
create table user_creations (id text primary key, organization_id text not null references organizations(id), actor_id text not null, user_id text not null, idempotency_key text not null, payload_hash text not null check(length(payload_hash)=64), actor_authorized boolean not null constraint creation_actor_authorized check(actor_authorized), created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,user_id) references users(organization_id,id) deferrable initially deferred);
create table account_status_changes (id text primary key, organization_id text not null references organizations(id), actor_id text not null, user_id text not null, idempotency_key text not null, requested_status text not null check(requested_status in ('active','inactive','suspended')), expected_version integer not null, actual_version integer not null, actor_authorized boolean not null constraint status_actor_authorized check(actor_authorized), target_exists boolean not null constraint status_target_exists check(target_exists), preserves_admin boolean not null constraint status_preserves_admin check(preserves_admin), created_at text not null, constraint status_version_matches check(expected_version=actual_version), unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,user_id) references users(organization_id,id));
create index role_changes_org_retention on role_changes(organization_id,created_at);
create index user_creations_org_retention on user_creations(organization_id,created_at);
create index account_status_changes_org_retention on account_status_changes(organization_id,created_at);
create table bootstrap_state (singleton integer primary key check(singleton=1), organization_id text not null unique references organizations(id) deferrable initially deferred, payload_hash text not null check(length(payload_hash)=64), initialized_at text not null);
create table audit_retention_holds (audit_log_id text primary key references audit_logs(id), organization_id text not null references organizations(id), reason text not null check(length(trim(reason)) between 1 and 500), decision_owner text not null check(length(trim(decision_owner)) between 1 and 120), review_at text not null, created_at text not null, updated_at text not null);

create table service_fields (id text primary key, organization_id text not null references organizations(id), code text not null check(length(code) between 1 and 64), name text not null check(length(trim(name)) between 1 and 120), active integer not null default 1 check(active in (0,1)), version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, unique(organization_id,code), unique(organization_id,id));
create table service_roles (id text primary key, organization_id text not null references organizations(id), field_id text not null, code text not null check(length(code) between 1 and 64), name text not null check(length(trim(name)) between 1 and 120), slots_required integer not null default 1 check(slots_required between 1 and 99), active integer not null default 1 check(active in (0,1)), criticality text not null default 'normal' check(criticality in ('normal','critical')), version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, foreign key(organization_id,field_id) references service_fields(organization_id,id), unique(organization_id,code), unique(organization_id,id));
create table servants (id text primary key, organization_id text not null references organizations(id), user_id text, display_name text not null check(length(trim(display_name)) between 1 and 120), status text not null default 'active' check(status in ('active','inactive','pending_review')), telegram_chat_id text, telegram_user_id text, is_backup integer not null default 0 check(is_backup in (0,1)), administrative_note text, version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, foreign key(organization_id,user_id) references users(organization_id,id), unique(organization_id,id), unique(organization_id,user_id), unique(organization_id,telegram_chat_id));
create unique index servants_telegram_user_unique on servants(organization_id,telegram_user_id) where telegram_user_id is not null;
create table servant_capabilities (id text primary key, organization_id text not null references organizations(id), servant_id text not null, service_role_id text not null, status text not null default 'active' check(status in ('active','inactive','pending_approval')), approved_by text, approved_at text, monthly_assignment_limit integer check(monthly_assignment_limit between 1 and 99), version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, foreign key(organization_id,servant_id) references servants(organization_id,id), foreign key(organization_id,service_role_id) references service_roles(organization_id,id), foreign key(organization_id,approved_by) references users(organization_id,id), check((status='active' and approved_by is not null and approved_at is not null) or status<>'active'), unique(organization_id,servant_id,service_role_id));
create table capability_approvers (id text primary key, organization_id text not null references organizations(id), service_role_id text not null, user_id text not null, active integer not null default 1 check(active in (0,1)), created_at text not null, updated_at text not null, foreign key(organization_id,service_role_id) references service_roles(organization_id,id), foreign key(organization_id,user_id) references users(organization_id,id), unique(organization_id,service_role_id,user_id));
create table availability_blocks (id text primary key, organization_id text not null references organizations(id), servant_id text not null, starts_at text not null, ends_at text not null check(ends_at>starts_at), block_type text not null default 'unavailable' check(block_type in ('unavailable','preference')), note_private text, version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, foreign key(organization_id,servant_id) references servants(organization_id,id), unique(organization_id,id));
create table worship_services (id text primary key, organization_id text not null references organizations(id), starts_at text not null, assembly_at text not null check(assembly_at<=starts_at), ends_at text not null check(ends_at>starts_at), location text not null check(length(trim(location)) between 1 and 160), status text not null default 'draft' check(status in ('draft','scheduled','completed','postponed','cancelled')), theme text, notes text, cancellation_reason text, title text, published_at text, rescheduled_from_json jsonb, version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, check(status<>'cancelled' or cancellation_reason is not null), unique(organization_id,id));
create table assignments (id text primary key, organization_id text not null references organizations(id), worship_service_id text not null, service_role_id text not null, servant_id text not null, status text not null default 'draft' check(status in ('draft','awaiting_confirmation','accepted','unavailable','needs_replacement','reassigned','absent','completed','cancelled')), slot_number integer not null default 1 check(slot_number between 1 and 99), confirmed_at text, source_import_row_id text, version integer not null default 1 check(version>0), created_at text not null, updated_at text not null, foreign key(organization_id,worship_service_id) references worship_services(organization_id,id), foreign key(organization_id,service_role_id) references service_roles(organization_id,id), foreign key(organization_id,servant_id) references servants(organization_id,id), unique(organization_id,id));
create unique index assignments_active_slot_number on assignments(organization_id,worship_service_id,service_role_id,slot_number) where status not in ('cancelled','reassigned');
create index services_org_time on worship_services(organization_id,starts_at,id);
create index assignments_org_servant_status on assignments(organization_id,servant_id,status,id);
create index availability_org_servant_time on availability_blocks(organization_id,servant_id,starts_at,ends_at);

create table worship_service_creations (id text primary key, organization_id text not null, actor_id text not null, worship_service_id text not null, idempotency_key text not null, payload_hash text not null check(length(payload_hash)=64), actor_authorized boolean not null constraint service_creation_actor_authorized check(actor_authorized), created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,worship_service_id) references worship_services(organization_id,id) deferrable initially deferred);
create table worship_service_status_changes (id text primary key, organization_id text not null, actor_id text not null, worship_service_id text not null, idempotency_key text not null, requested_status text not null, expected_version integer not null, actual_version integer not null, actor_authorized boolean not null constraint service_status_actor_authorized check(actor_authorized), target_exists boolean not null constraint service_status_target_exists check(target_exists), created_at text not null, constraint service_status_version_matches check(expected_version=actual_version), unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,worship_service_id) references worship_services(organization_id,id));
create table assignment_creations (id text primary key, organization_id text not null, actor_id text not null, assignment_id text not null, idempotency_key text not null, payload_hash text not null check(length(payload_hash)=64), actor_authorized boolean not null constraint assignment_creation_actor_authorized check(actor_authorized), created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,assignment_id) references assignments(organization_id,id) deferrable initially deferred);
create table assignment_status_changes (id text primary key, organization_id text not null, actor_id text not null, assignment_id text not null, idempotency_key text not null, requested_status text not null, expected_version integer not null, actual_version integer not null, actor_authorized boolean not null constraint assignment_status_actor_authorized check(actor_authorized), target_exists boolean not null constraint assignment_status_target_exists check(target_exists), created_at text not null, constraint assignment_status_version_matches check(expected_version=actual_version), unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,assignment_id) references assignments(organization_id,id));
create table operational_mutation_receipts (id text primary key, organization_id text not null, actor_id text not null, idempotency_key text not null, action text not null, entity_id text not null, payload_hash text not null check(length(payload_hash)=64), actor_authorized boolean not null constraint operational_actor_authorized check(actor_authorized), created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id));

create table import_batches (id text primary key, organization_id text not null references organizations(id), uploaded_by text not null, original_filename text not null check(length(original_filename)<=180), checksum text not null check(length(checksum)=64), sheet_name text, mapping_json jsonb not null default '{}'::jsonb, date_format text check(date_format in ('dmy','mdy')), timezone text not null default 'Asia/Makassar', status text not null check(status in ('uploaded','validating','needs_review','ready','committing','committed','failed','rolled_back','expired')), expires_at text not null, committed_at text, version integer not null default 1, created_at text not null, updated_at text not null, foreign key(organization_id,uploaded_by) references users(organization_id,id), unique(organization_id,id));
create table import_rows (id text primary key, batch_id text not null references import_batches(id), organization_id text not null, row_number integer not null check(row_number between 1 and 5001), source_number text, raw_json jsonb not null, normalized_json jsonb not null, status text not null check(status in ('valid','warning','error','excluded','committed','skipped')), proposed_action text not null check(proposed_action in ('create','skip','merge_assignments','create_separate')), error_codes_json jsonb not null default '[]'::jsonb, warning_codes_json jsonb not null default '[]'::jsonb, override_starts_at text, warnings_acknowledged_at text, duplicate_service_id text, created_at text not null, updated_at text not null, unique(batch_id,row_number), unique(organization_id,id), foreign key(organization_id,batch_id) references import_batches(organization_id,id));
alter table assignments add foreign key(source_import_row_id) references import_rows(id);
create table import_resolutions (id text primary key, organization_id text not null, import_row_id text not null, field_name text not null check(field_name in ('preacher','mc','offering','location','duplicate')), resolution_type text not null check(resolution_type in ('link_existing','create_pending_review','exclude','skip','merge_assignments','create_separate')), target_entity_id text, resolved_by text not null, created_at text not null, foreign key(organization_id,import_row_id) references import_rows(organization_id,id), foreign key(organization_id,resolved_by) references users(organization_id,id), unique(import_row_id,field_name));
create table import_results (id text primary key, organization_id text not null, import_row_id text not null, entity_type text not null, entity_id text not null, action text not null check(action in ('created','skipped','merged','voided')), rollback_status text not null default 'available' check(rollback_status in ('available','voided','blocked')), created_at text not null, foreign key(organization_id,import_row_id) references import_rows(organization_id,id), unique(import_row_id,entity_type,entity_id));
create table import_commit_receipts (id text primary key, organization_id text not null, actor_id text not null, batch_id text not null, idempotency_key text not null, payload_hash text not null check(length(payload_hash)=64), created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,batch_id) references import_batches(organization_id,id));
create table import_resolution_receipts (id text primary key, organization_id text not null, actor_id text not null, import_row_id text not null, idempotency_key text not null, action text not null check(action='exclude'), created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,import_row_id) references import_rows(organization_id,id));
create table import_rollback_receipts (id text primary key, organization_id text not null, actor_id text not null, batch_id text not null, idempotency_key text not null, created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,batch_id) references import_batches(organization_id,id));
create table import_link_receipts (id text primary key, organization_id text not null, actor_id text not null, import_row_id text not null, field_name text not null check(field_name in ('preacher','mc')), target_servant_id text not null, idempotency_key text not null, created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,import_row_id) references import_rows(organization_id,id), foreign key(organization_id,target_servant_id) references servants(organization_id,id));
create table import_pending_receipts (id text primary key, organization_id text not null, actor_id text not null, import_row_id text not null, field_name text not null check(field_name in ('preacher','mc')), servant_id text not null, idempotency_key text not null, created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,import_row_id) references import_rows(organization_id,id), foreign key(organization_id,servant_id) references servants(organization_id,id));
create table import_action_receipts (id text primary key, organization_id text not null, actor_id text not null, import_row_id text not null, idempotency_key text not null, payload_hash text not null check(length(payload_hash)=64), created_at text not null, unique(organization_id,actor_id,idempotency_key), foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,import_row_id) references import_rows(organization_id,id));
create table import_batch_summaries (batch_id text primary key, organization_id text not null, summary_json jsonb not null, retained_until text not null, created_at text not null, updated_at text not null, foreign key(organization_id,batch_id) references import_batches(organization_id,id));

create table telegram_activation_codes (id text primary key, organization_id text not null, servant_id text not null, code_hash text not null check(length(code_hash)=64), expires_at text not null, attempts integer not null default 0 check(attempts between 0 and 5), consumed_at text, created_by text not null, created_at text not null, foreign key(organization_id,servant_id) references servants(organization_id,id), foreign key(organization_id,created_by) references users(organization_id,id), unique(organization_id,id));
create unique index telegram_activation_active on telegram_activation_codes(organization_id,servant_id) where consumed_at is null;
create table telegram_callback_grants (id text primary key, organization_id text not null, servant_id text not null, assignment_id text not null, action text not null check(action in ('accept','unavailable')), nonce_hash text not null check(length(nonce_hash)=64), expires_at text not null, consumed_at text, created_at text not null, foreign key(organization_id,servant_id) references servants(organization_id,id), foreign key(organization_id,assignment_id) references assignments(organization_id,id), unique(organization_id,nonce_hash), unique(organization_id,id));
create table telegram_notification_intents (id text primary key, organization_id text not null, servant_id text not null, assignment_id text, event_type text not null check(event_type in ('assignment_confirmation','assignment_reminder','critical_reminder')), idempotency_key text not null, due_at text not null, status text not null default 'pending' check(status in ('pending','sending','accepted_by_api','failed','cancelled')), attempt_count integer not null default 0 check(attempt_count between 0 and 3), last_error_category text, payload_json jsonb not null, created_at text not null, updated_at text not null, foreign key(organization_id,servant_id) references servants(organization_id,id), foreign key(organization_id,assignment_id) references assignments(organization_id,id), unique(organization_id,idempotency_key));
create table telegram_webhook_updates (organization_id text not null, update_id text not null, received_at text not null, primary key(organization_id,update_id));
create table telegram_emergency_reports (id text primary key, organization_id text not null, assignment_id text not null, servant_id text not null, status text not null default 'open' check(status in ('open','closed')), created_at text not null, foreign key(organization_id,assignment_id) references assignments(organization_id,id), foreign key(organization_id,servant_id) references servants(organization_id,id));
create unique index telegram_emergency_one_open on telegram_emergency_reports(organization_id,assignment_id) where status='open';
create table telegram_callback_receipts (id text primary key, organization_id text not null, callback_grant_id text not null, assignment_id text not null, expected_version integer not null, actual_version integer not null, actor_matches boolean not null check(actor_matches), state_matches boolean not null check(state_matches), created_at text not null, check(expected_version=actual_version), foreign key(organization_id,callback_grant_id) references telegram_callback_grants(organization_id,id), foreign key(organization_id,assignment_id) references assignments(organization_id,id), unique(organization_id,callback_grant_id));
create table telegram_activation_attempts (organization_id text not null, telegram_user_id text not null, window_started_at text not null, attempt_count integer not null check(attempt_count between 1 and 5), updated_at text not null, primary key(organization_id,telegram_user_id));
create table telegram_activation_requests (id text primary key, organization_id text not null, actor_id text not null, servant_id text not null, activation_id text not null, idempotency_key text not null, created_at text not null, foreign key(organization_id,actor_id) references users(organization_id,id), foreign key(organization_id,servant_id) references servants(organization_id,id), foreign key(organization_id,activation_id) references telegram_activation_codes(organization_id,id), unique(organization_id,actor_id,idempotency_key));
create table replacement_cases (id text primary key, organization_id text not null, service_id text not null, assignment_id text not null, service_role_id text not null, status text not null default 'open' check(status in ('open','resolved','escalated_manual','cancelled')), urgency text not null default 'standard' check(urgency in ('standard','critical')), reason text not null, resolved_assignment_id text, resolved_by text, resolved_at text, created_by text, created_at text not null, updated_at text not null, foreign key(organization_id,service_id) references worship_services(organization_id,id), foreign key(organization_id,assignment_id) references assignments(organization_id,id), foreign key(organization_id,service_role_id) references service_roles(organization_id,id), foreign key(organization_id,resolved_assignment_id) references assignments(organization_id,id), foreign key(organization_id,resolved_by) references users(organization_id,id), foreign key(organization_id,created_by) references users(organization_id,id), unique(organization_id,id));
create unique index replacement_cases_one_open on replacement_cases(organization_id, assignment_id) where status='open';
create index replacement_cases_lookup on replacement_cases(organization_id, status, urgency, created_at);
create index replacement_cases_service on replacement_cases(organization_id, service_id, status);
create table replacement_resolutions (id text primary key, organization_id text not null, case_id text not null, actor_id text not null, idempotency_key text not null, payload_hash text not null check(length(payload_hash)=64), created_at text not null, foreign key(organization_id,case_id) references replacement_cases(organization_id,id), foreign key(organization_id,actor_id) references users(organization_id,id), unique(organization_id,actor_id,idempotency_key));
create table attendance_records (id text primary key, organization_id text not null, service_id text not null, assignment_id text not null, servant_id text not null, status text not null check(status in ('present','late','absent','replaced')), checkin_time text, notes text, recorded_by text not null, created_at text not null, updated_at text not null, foreign key(organization_id,service_id) references worship_services(organization_id,id), foreign key(organization_id,assignment_id) references assignments(organization_id,id), foreign key(organization_id,servant_id) references servants(organization_id,id), foreign key(organization_id,recorded_by) references users(organization_id,id), unique(organization_id,assignment_id), unique(organization_id,id));
create index attendance_records_service on attendance_records(organization_id, service_id, status);
create index attendance_records_servant on attendance_records(organization_id, servant_id, status);
create table service_notes (id text primary key, organization_id text not null, service_id text, servant_id text, category text not null check(category in ('operational','subject_visible','restricted')), title text not null, content text not null, created_by text not null, created_at text not null, updated_at text not null, foreign key(organization_id,service_id) references worship_services(organization_id,id), foreign key(organization_id,servant_id) references servants(organization_id,id), foreign key(organization_id,created_by) references users(organization_id,id), unique(organization_id,id));
create index service_notes_category on service_notes(organization_id, category, created_at);
create index service_notes_service on service_notes(organization_id, service_id);
create index service_notes_servant on service_notes(organization_id, servant_id);
create table service_notes_acl (id text primary key, organization_id text not null, note_id text not null, user_id text not null, granted_by text not null, created_at text not null, foreign key(organization_id,note_id) references service_notes(organization_id,id) on delete cascade, foreign key(organization_id,user_id) references users(organization_id,id), foreign key(organization_id,granted_by) references users(organization_id,id), unique(organization_id,note_id,user_id));

insert into roles(id,code,name) values ('super_admin','super_admin','Super Admin'),('admin','admin','Admin/Sekretariat'),('worship_coordinator','worship_coordinator','Koordinator Ibadah'),('field_coordinator','field_coordinator','Koordinator Bidang'),('servant','servant','Pelayan'),('public_viewer','public_viewer','Jemaat/publik (nonaktif)');
