create function spi_audit_immutable() returns trigger language plpgsql as $$ begin raise exception 'Audit is append only'; end $$;
create trigger audit_no_update before update on audit_logs for each row execute function spi_audit_immutable();
create trigger audit_no_delete before delete on audit_logs for each row execute function spi_audit_immutable();
create function spi_user_role_guard() returns trigger language plpgsql as $$ begin if new.role_id='public_viewer' then raise exception 'Public access disabled for MVP'; end if; return new; end $$;
create trigger no_public_role before insert or update of role_id on user_roles for each row execute function spi_user_role_guard();
create function spi_status_transition_guard() returns trigger language plpgsql as $$ begin if exists(select 1 from users where organization_id=new.organization_id and id=new.user_id and status=new.requested_status) then raise exception 'Account status transition must change status'; end if; return new; end $$;
create trigger account_status_requires_transition before insert on account_status_changes for each row execute function spi_status_transition_guard();
create function spi_retention_org_guard() returns trigger language plpgsql as $$ begin if not exists(select 1 from audit_logs where id=new.audit_log_id and organization_id=new.organization_id) then raise exception 'Retention hold audit organization mismatch'; end if; return new; end $$;
create trigger retention_hold_same_organization before insert or update of audit_log_id,organization_id on audit_retention_holds for each row execute function spi_retention_org_guard();
create function spi_capability_guard() returns trigger language plpgsql as $$ begin if new.status='active' and not exists(select 1 from capability_approvers where organization_id=new.organization_id and service_role_id=new.service_role_id and user_id=new.approved_by and active=1) then raise exception 'Capability approver not designated'; end if; return new; end $$;
create trigger capability_active_requires_approver before insert or update of status,approved_by,service_role_id,organization_id on servant_capabilities for each row execute function spi_capability_guard();
create function spi_scope_guard() returns trigger language plpgsql as $$ begin if (new.scope_type='service' and not exists(select 1 from worship_services where organization_id=new.organization_id and id=new.scope_id)) or (new.scope_type='field' and not exists(select 1 from service_fields where organization_id=new.organization_id and id=new.scope_id)) then raise exception 'Coordinator scope target mismatch'; end if; return new; end $$;
create trigger coordinator_scope_target before insert or update of organization_id,scope_type,scope_id on coordinator_scopes for each row execute function spi_scope_guard();
create function spi_assignment_guard() returns trigger language plpgsql as $$ declare assignment_count integer; assignment_limit integer; proposed_month text; begin if new.status in ('cancelled','reassigned') then return new; end if; if not exists(select 1 from servants where organization_id=new.organization_id and id=new.servant_id and status='active') then raise exception 'Assignment servant inactive'; end if; if not exists(select 1 from servant_capabilities where organization_id=new.organization_id and servant_id=new.servant_id and service_role_id=new.service_role_id and status='active') then raise exception 'Assignment capability unapproved'; end if; if exists(select 1 from availability_blocks b join worship_services s on s.organization_id=new.organization_id and s.id=new.worship_service_id where b.organization_id=new.organization_id and b.servant_id=new.servant_id and b.block_type='unavailable' and b.starts_at<s.ends_at and b.ends_at>s.starts_at) then raise exception 'Assignment availability conflict'; end if; select monthly_assignment_limit into assignment_limit from servant_capabilities where organization_id=new.organization_id and servant_id=new.servant_id and service_role_id=new.service_role_id; if assignment_limit is not null then select substr(starts_at,1,7) into proposed_month from worship_services where organization_id=new.organization_id and id=new.worship_service_id; select count(*) into assignment_count from assignments a join worship_services s on s.organization_id=a.organization_id and s.id=a.worship_service_id where a.id<>new.id and a.organization_id=new.organization_id and a.servant_id=new.servant_id and a.service_role_id=new.service_role_id and a.status not in ('cancelled','reassigned') and substr(s.starts_at,1,7)=proposed_month; if assignment_count>=assignment_limit then raise exception 'Assignment monthly limit exceeded'; end if; end if; return new; end $$;
create trigger assignment_integrity before insert or update of status,servant_id,service_role_id,worship_service_id on assignments for each row execute function spi_assignment_guard();

revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

commit;
